/**
 * A single event emitted by an {@link AgentSession} stream.
 *
 * The shape is intentionally open: a small set of well-known fields (`type`,
 * `id`, `streamId`) are always present, while event-specific data is carried in
 * additional properties. This mirrors the loosely-typed nature of streamed
 * agent protocols where new event kinds can be introduced without breaking
 * consumers.
 */
export interface AgentEvent {
  /** Discriminator identifying the kind of event (e.g. `stream_start`). */
  type: string;
  /** Unique identifier for this event within the session. */
  id: string;
  /** Identifier of the stream this event belongs to. */
  streamId: string;
  /** Additional, event-specific fields. */
  [key: string]: unknown;
}

/**
 * A user-supplied, partial {@link AgentEvent}. When queued on a mock session
 * the missing bookkeeping fields (`id`, `streamId`) are filled in
 * automatically. Only the event `type` is required.
 */
export type MockAgentEvent = Partial<AgentEvent> & { type: string };

/** Send a message to the agent. */
export interface AgentSendMessage {
  type: 'message';
  /** The message content. */
  content?: unknown;
  [key: string]: unknown;
}

/** Update mutable session properties. */
export interface AgentSendUpdate {
  type: 'update';
  /** The properties to merge into the session state. */
  update?: Record<string, unknown>;
  [key: string]: unknown;
}

/** Respond to one or more outstanding elicitations. */
export interface AgentSendElicitations {
  type: 'elicitations';
  /** The elicitation responses, one per outstanding request. */
  elicitations?: unknown[];
  [key: string]: unknown;
}

/** Invoke an agent-defined action. */
export interface AgentSendAction {
  type: 'action';
  /** The action to invoke. */
  action?: unknown;
  [key: string]: unknown;
}

/** The union of payloads accepted by {@link AgentSession.send}. */
export type AgentSend =
  | AgentSendMessage
  | AgentSendUpdate
  | AgentSendElicitations
  | AgentSendAction;

/** Options controlling how a queued response is streamed. */
export interface PushResponseOptions {
  /**
   * When `true` the stream is left open after the queued events are emitted (no
   * terminal `stream_end` event is appended), allowing further events to be
   * pushed with `pushToStream`.
   */
  keepOpen?: boolean;
}

/** Options accepted by {@link AgentSession.stream}. */
export interface StreamOptions {
  /** Stream a specific stream instead of the most recent one. */
  streamId?: string;
  /** Begin streaming at the event with this id (inclusive). */
  eventId?: string;
}

/**
 * A bidirectional connection to a running agent.
 *
 * Callers drive the agent with {@link send} and observe its output by iterating
 * the async stream returned from {@link stream}. The full ordered history of
 * events emitted across every stream is available via {@link events}.
 */
export interface AgentSession {
  /**
   * Send a payload to the agent, returning the id of the stream that carries
   * the response.
   */
  send(payload: AgentSend): Promise<{ streamId: string }>;

  /**
   * Iterate the events of a stream. Without options the most recently created
   * stream is used. The iterator suspends while the stream is still open and
   * resolves once it is closed.
   */
  stream(options?: StreamOptions): AsyncIterableIterator<AgentEvent>;

  /** Abort any in-flight streams. */
  abort(): Promise<void>;

  /** The complete, ordered history of events emitted across all streams. */
  readonly events: AgentEvent[];
}
