import type {
  AgentEvent,
  AgentSend,
  AgentSession,
  MockAgentEvent,
  PushResponseOptions,
  StreamOptions,
} from './types.js';

/** A queued response consumed by the next {@link MockAgentSession.send} call. */
interface QueuedResponse {
  events: MockAgentEvent[];
  keepOpen: boolean;
}

/** Internal per-stream bookkeeping. */
interface MockStream {
  streamId: string;
  events: AgentEvent[];
  /** `true` while the stream may still receive more events. */
  open: boolean;
  /** Resolvers for consumers suspended waiting for more events. */
  waiters: Array<() => void>;
}

/**
 * An in-memory {@link AgentSession} for tests.
 *
 * Instead of talking to a real backend, responses are pre-programmed with
 * {@link pushResponse} (or streamed incrementally with {@link pushToStream}) and
 * replayed when {@link send} is called. Session lifecycle events
 * (`stream_start`/`stream_end`) are injected automatically and every event that
 * flows through the session is recorded in {@link events} for later assertions.
 */
export class MockAgentSession implements AgentSession {
  /** Mutable session state, updated by `update` sends. */
  readonly sessionState: Record<string, unknown> = {};

  private readonly streams: MockStream[] = [];
  private readonly streamsById = new Map<string, MockStream>();
  private readonly responseQueue: QueuedResponse[] = [];
  private readonly history: AgentEvent[] = [];

  private streamCounter = 0;
  private eventCounter = 0;

  constructor(initialEvents: AgentEvent[] = []) {
    for (const event of initialEvents) {
      const streamId = event.streamId ?? this.nextStreamId();
      const stream = this.getOrCreateStream(streamId);
      const materialized: AgentEvent = {
        ...event,
        type: event.type,
        id: event.id ?? this.nextEventId(),
        streamId,
      };
      this.record(stream, materialized);
    }
    // Streams provided up-front are treated as complete unless they were left
    // without a terminal event.
    for (const stream of this.streams) {
      stream.open = !MockAgentSession.hasStreamEnd(stream.events);
    }
  }

  /**
   * Queue a partial response to be replayed by the next {@link send} call.
   * Multiple calls queue multiple responses which are consumed in order, one
   * per send.
   */
  pushResponse(events: MockAgentEvent[], options?: PushResponseOptions): void {
    this.responseQueue.push({
      events: events.map((event) => ({ ...event })),
      keepOpen: options?.keepOpen ?? false,
    });
  }

  async send(payload: AgentSend): Promise<{ streamId: string }> {
    if (payload.type === 'action') {
      throw new Error(
        `Actions not supported in MockAgentSession: ${payload.type}`,
      );
    }

    const response = this.responseQueue.shift() ?? {
      events: [],
      keepOpen: false,
    };

    const parts: MockAgentEvent[] = response.events.map((event) => ({
      ...event,
    }));

    // Prepend a stream_start event if none was queued.
    if (!parts.some((part) => part.type === 'stream_start')) {
      parts.unshift({ type: 'stream_start' });
    }

    // Inject the events implied by the payload immediately after stream_start.
    const injected = this.buildInjectedEvents(payload);
    const startIndex = parts.findIndex((part) => part.type === 'stream_start');
    parts.splice(startIndex + 1, 0, ...injected);

    // Append a terminal stream_end unless the stream should stay open or one is
    // already present.
    if (
      !response.keepOpen &&
      !parts.some((part) => part.type === 'stream_end')
    ) {
      parts.push({ type: 'stream_end' });
    }

    const stream = this.createStream();
    for (const part of parts) {
      this.record(stream, this.materialize(part, stream.streamId));
    }
    stream.open = !MockAgentSession.hasStreamEnd(stream.events);

    return { streamId: stream.streamId };
  }

  stream(options: StreamOptions = {}): AsyncIterableIterator<AgentEvent> {
    const { streamId, eventId } = options;

    let stream: MockStream | undefined;
    if (streamId !== undefined) {
      stream = this.streamsById.get(streamId);
      if (!stream) {
        throw new Error(`No stream found with streamId: ${streamId}`);
      }
    } else {
      stream = this.streams[this.streams.length - 1];
      if (!stream) {
        throw new Error('No streams available to stream from');
      }
    }

    let start = 0;
    if (eventId !== undefined) {
      const index = stream.events.findIndex((event) => event.id === eventId);
      if (index === -1) {
        throw new Error(`No event found with eventId: ${eventId}`);
      }
      start = index;
    }

    return this.iterate(stream, start);
  }

  async abort(): Promise<void> {
    for (const stream of this.streams) {
      if (!stream.open) {
        continue;
      }
      this.record(
        stream,
        this.materialize({ type: 'stream_end', reason: 'aborted' }, stream.streamId),
      );
      stream.open = false;
      this.wake(stream);
    }
  }

  /**
   * Append events to an already-created stream, resuming any suspended
   * consumers. When `close` is true a terminal `stream_end` (reason
   * `completed`) is appended unless one is already present.
   */
  pushToStream(
    streamId: string,
    events: MockAgentEvent[],
    options?: { close?: boolean },
  ): void {
    const stream = this.streamsById.get(streamId);
    if (!stream) {
      throw new Error(`No stream found with streamId: ${streamId}`);
    }

    for (const part of events) {
      this.record(stream, this.materialize(part, streamId));
    }

    if (options?.close && !MockAgentSession.hasStreamEnd(stream.events)) {
      this.record(
        stream,
        this.materialize({ type: 'stream_end', reason: 'completed' }, streamId),
      );
    }

    stream.open = !MockAgentSession.hasStreamEnd(stream.events);
    this.wake(stream);
  }

  get events(): AgentEvent[] {
    return [...this.history];
  }

  // --- internals -----------------------------------------------------------

  private buildInjectedEvents(payload: AgentSend): MockAgentEvent[] {
    switch (payload.type) {
      case 'message': {
        const { type: _type, ...rest } = payload;
        return [{ ...rest, type: 'message', role: 'user' }];
      }
      case 'update': {
        const { type: _type, update, ...rest } = payload;
        const data = update ?? rest;
        Object.assign(this.sessionState, data);
        return [{ ...data, type: 'session_update' }];
